// Driver-owned adapter contract. Not an upstream Bionic or Digitalis header.
#ifndef PENGUDROID_BRIDGE_TLS_ADAPTER_H_
#define PENGUDROID_BRIDGE_TLS_ADAPTER_H_
#include <cstddef>
#include <cstdint>
#include <dlfcn.h>
#include <pthread.h>
#include "berberis/base/checks.h"
namespace berberis {
struct PengudroidBridgeTlsView {
  void* guest_pthread;
  void* bionic_tls;
  uintptr_t host_pthread;
  int32_t tid;
  int32_t pid;
  void* guest_state;
};
static_assert(sizeof(PengudroidBridgeTlsView) == 40);
inline PengudroidBridgeTlsView GetPengudroidBridgeTls(void* guest_tp = nullptr,
                                                     void* guest_state = nullptr) {
  using Helper = int (*)(uint64_t, size_t, void*, void*, PengudroidBridgeTlsView*);
  static const auto helper = reinterpret_cast<Helper>(
      dlsym(RTLD_DEFAULT, "pengudroid_bridge_tls_v1"));
  CHECK(helper != nullptr);
  PengudroidBridgeTlsView view{};
  // The helper also requires PENGUDROID_BRIDGE_TLS=1. Missing/disabled or
  // mismatched helpers fail closed instead of exposing a glibc pthread as Bionic.
  CHECK_EQ(helper(UINT64_C(0xf953e6ea42974914), sizeof(view), guest_tp, guest_state, &view), 0);
  CHECK(view.guest_pthread != nullptr);
  CHECK(view.bionic_tls != nullptr);
  CHECK_EQ(view.host_pthread, static_cast<uintptr_t>(pthread_self()));
  return view;
}
}  // namespace berberis
#endif
